function parse_nested_parens(paren_string){
  const groups = paren_string.split(' ');
  const results = [];
  for (const group of groups) {
    let maxDepth = 0;
    let currentDepth = 0;
    for (const char of group) {
      if (char === '(') {
        currentDepth++;
        if (currentDepth > maxDepth) {
          maxDepth = currentDepth;
        }
      } else if (char === ')') {
        currentDepth--;
      }
    }
    results.push(maxDepth);
  }
  return results;
}

