function last(arr, x){
  let start = 0;
  let end = arr.length - 1;

  while(start <= end){
    let mid = Math.floor((start + end) / 2);

    if(arr[mid] === x){
      if(mid === arr.length - 1 || arr[mid + 1] !== x){
        return mid;
      }
      start = mid + 1;
    } else if(arr[mid] < x){
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  return -1;
}
